import test from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import ts from 'typescript';
const encode = source => 'data:text/javascript;base64,' + Buffer.from(source).toString('base64');
const compile = source => ts.transpileModule(source, { compilerOptions: { target: ts.ScriptTarget.ES2022, module: ts.ModuleKind.ESNext } }).outputText;
const modelUrl = encode(compile(readFileSync(new URL('../lib/model.ts', import.meta.url), 'utf8')));
const model = await import(modelUrl);
const accountUrl=encode(compile(readFileSync(new URL('../lib/owner-account.ts',import.meta.url),'utf8')).replace("'./model'",JSON.stringify(modelUrl)));
const {ownerAccount,ownerStatementHtml}=await import(accountUrl);
const contractUrl=encode(compile(readFileSync(new URL('../lib/contracts.ts',import.meta.url),'utf8')).replace("'./model'",JSON.stringify(modelUrl)));
const {contractSnapshot,contractHtml}=await import(contractUrl);
const activityUrl=encode(compile(readFileSync(new URL('../lib/activity.ts',import.meta.url),'utf8')));
const inventoryUrl=encode(compile(readFileSync(new URL('../lib/inventory.ts',import.meta.url),'utf8')).replace("'./model'",JSON.stringify(modelUrl)));
const activity=await import(activityUrl),inventory=await import(inventoryUrl);
let validation = compile(readFileSync(new URL('../lib/validation.ts', import.meta.url), 'utf8'));
validation = validation.replace("'./activity'",JSON.stringify(activityUrl)).replace("'./inventory'",JSON.stringify(inventoryUrl)).replace("'./contracts'",JSON.stringify(contractUrl)).replace("'./owner-account'",JSON.stringify(accountUrl)).replace("'./model'", JSON.stringify(modelUrl)).replace("'zod'", JSON.stringify(import.meta.resolve('zod')));
const { applyMutation, stateSchema, validateRelations } = await import(encode(validation));
const { demoState, totals, balanceFor, dueDate, billed, emptyState } = model;
const save = (state, entity, data) => applyMutation(state, { action: 'save', entity, data });
const unit = (parent,id,label) => ({...parent,id,name:parent.name,reference:undefined,parentId:parent.id,unitLabel:label,floor:label});
test('splitting a rented building preserves payments, lease IDs and financial totals',()=>{const s=demoState(),parent=s.properties[0],before=totals(s,s.leases[0].firstMonth);const next=applyMutation(s,{action:'addUnits',data:{propertyId:parent.id,units:[unit(parent,'unit-a','RDC'),unit(parent,'unit-b','R+1')],moveExistingTo:'unit-a'}});assert.equal(next.leases[0].id,s.leases[0].id);assert.equal(next.leases[0].propertyId,'unit-a');assert.deepEqual(next.payments.map(({ownerId,commissionRate,rentBase,...p})=>p),s.payments);assert.equal(totals(next,s.leases[0].firstMonth).collected,before.collected);assert.equal(totals(next,s.leases[0].firstMonth).expected,before.expected);assert.equal(totals(next,s.leases[0].firstMonth).occupied,before.occupied);assert.equal(model.rentalProperties(next).length,model.rentalProperties(s).length+1);assert.equal(s.properties.length,5);});
test('an occupied building requires an explicit destination before splitting',()=>{const s=demoState(),p=s.properties[0];assert.throws(()=>applyMutation(s,{action:'addUnits',data:{propertyId:p.id,units:[unit(p,'unit-a','RDC')]}}),/reprend/);assert.equal(s.leases[0].propertyId,p.id);});
test('one building supports two simultaneous tenants in separate floors',()=>{const s=demoState(),p=s.properties[0];let next=applyMutation(s,{action:'addUnits',data:{propertyId:p.id,units:[unit(p,'unit-a','RDC'),unit(p,'unit-b','R+1')],moveExistingTo:'unit-a'}});next=save(next,'leases',{...s.leases[0],id:'second-floor-lease',propertyId:'unit-b',tenantId:s.tenants[1].id});assert.equal(model.propertyStatus(next,next.properties.find(p=>p.id==='unit-a')),'occupied');assert.equal(model.propertyStatus(next,next.properties.find(p=>p.id==='unit-b')),'occupied');assert.equal(totals(next,s.leases[0].firstMonth).occupied,4);});
test('grouped buildings cannot receive a new lease or a direct short stay',()=>{const s=demoState(),p=s.properties[3],next=applyMutation(s,{action:'addUnits',data:{propertyId:p.id,units:[unit(p,'unit-free','RDC')]}});assert.throws(()=>save(next,'leases',{...s.leases[0],id:'bad-parent',propertyId:p.id}),/logement ou l’étage/);assert.throws(()=>save(next,'reservations',{id:'bad-stay',propertyId:p.id,name:'Client',phone:'',startDate:'2028-01-01',endDate:'2028-01-03',total:20000,paid:0,status:'confirmed',note:''}),/logement ou l’étage/);});
test('duplicate floor labels and nested buildings are rejected atomically',()=>{const s=demoState(),p=s.properties[3];assert.throws(()=>applyMutation(s,{action:'addUnits',data:{propertyId:p.id,units:[unit(p,'unit-a','RDC'),unit(p,'unit-b','rdc')]}}),/même nom|existe déjà/);const next=applyMutation(s,{action:'addUnits',data:{propertyId:p.id,units:[unit(p,'unit-a','RDC')]}});const child=next.properties.find(p=>p.id==='unit-a');assert.throws(()=>applyMutation(next,{action:'addUnits',data:{propertyId:child.id,units:[unit(child,'unit-nested','Chambre')]}}),/principal/);});
test('property references survive edits and are never reused after deletion',()=>{let s=demoState();s=save(s,'tasks',s.tasks[0]);const deleted=s.properties[4],kept=s.properties[3];s=applyMutation(s,{action:'delete',entity:'properties',data:{id:deleted.id}});s=save(s,'properties',{...deleted,id:'new-property',name:'Nouveau bien',reference:undefined});assert.equal(s.properties.find(p=>p.id===kept.id).reference,kept.reference);assert.notEqual(s.properties.find(p=>p.id==='new-property').reference,deleted.reference);assert.equal(new Set(s.properties.map(p=>p.reference)).size,s.properties.length);});
test('building changes propagate ownership and address to its units',()=>{const s=demoState(),p=s.properties[3];let next=applyMutation(s,{action:'addUnits',data:{propertyId:p.id,units:[unit(p,'unit-a','RDC')]}});next=save(next,'owners',{id:'new-owner',name:'Propriétaire exemple',phone:'',email:''});next=save(next,'properties',{...next.properties.find(v=>v.id===p.id),city:'Thiès',address:'Quartier exemple',ownerId:'new-owner'});const child=next.properties.find(p=>p.id==='unit-a');assert.equal(child.ownerId,'new-owner');assert.equal(child.city,'Thiès');assert.equal(child.address,'Quartier exemple');});
test('appointments retain subject and time and reject invalid hours',()=>{const s=demoState(),t={...s.tasks[0],category:'visit',time:'14:30',contact:'Contact exemple',note:'Visite du premier étage'};assert.equal(save(s,'tasks',t).tasks[0].time,'14:30');assert.throws(()=>save(s,'tasks',{...t,time:'25:00'}));stateSchema.parse(s);});
test('future confirmed reservations are not counted as currently occupied',()=>{const s=demoState(),p=s.properties[3],before=totals(s,model.currentMonth()).occupied;s.reservations.push({id:'future-stay',propertyId:p.id,name:'Voyageur',phone:'',startDate:'2029-01-01',endDate:'2029-01-03',total:20000,paid:0,status:'confirmed',note:''});assert.equal(totals(s,model.currentMonth()).occupied,before);});
test('example state is valid and has consistent references', () => { const s = demoState(); stateSchema.parse(s); validateRelations(s); });
test('partial payments retain the exact outstanding balance', () => { const s = demoState(); const l = s.leases[1]; assert.equal(balanceFor(s,l,l.firstMonth),175000); });
test('deposits are excluded from income', () => { const s = demoState(); assert.equal(totals(s,s.leases[0].firstMonth).collected,400000); });
test('commissions exclude charges and deposits', () => { const s = demoState(); s.leases[0].commissionRate = 10; assert.equal(totals(s,s.leases[0].firstMonth).fees,18500); });
test('a partial payment can settle a bill exactly', () => { const s = demoState(); const l=s.leases[1]; const next=save(s,'payments',{...s.payments[1],id:'extra',reference:'SECOND-VERSEMENT',amount:175000}); assert.equal(balanceFor(next,l,l.firstMonth),0); assert.equal(s.payments.length,2); });
test('overpayments are rejected', () => { const s = demoState(); assert.throws(()=>save(s,'payments',{...s.payments[1],id:'extra',reference:'TROP-PERCU',amount:175001}),/solde/); });
test('invalid dates are rejected', () => { const s = demoState(); assert.throws(()=>save(s,'payments',{...s.payments[1],date:'2026-02-30'})); });
test('deleting a rented property is blocked', () => { const s=demoState(); assert.throws(()=>applyMutation(s,{action:'delete',entity:'properties',data:{id:s.properties[0].id}}),/bien/); });
test('overlapping leases are rejected', () => { const s=demoState(); assert.throws(()=>save(s,'leases',{...s.leases[0],id:'overlap'}),/autre bail/); });
test('stay dates cannot overlap an existing lease', () => { const s=demoState(); assert.throws(()=>save(s,'reservations',{id:'stay',propertyId:s.properties[0].id,name:'Voyageur',phone:'',startDate:s.leases[0].firstMonth+'-10',endDate:s.leases[0].firstMonth+'-12',total:100000,paid:0,status:'confirmed',note:''}),/bail/); });
test('invalid or foreign file links are rejected', () => { const s=demoState(); assert.throws(()=>save(s,'attachments',{id:'unsafe',name:'Document',propertyId:'',url:'https://example.com/a.pdf',type:'application/pdf',date:'2026-10-17'})); });
test('February due dates are clamped correctly', () => { assert.equal(dueDate({...demoState().leases[0],dueDay:31},'2026-02'),'2026-02-28'); });
test('months before tracking are not billed', () => { assert.equal(billed({...demoState().leases[0],startDate:'2026-01-01',firstMonth:'2026-10'},'2026-09'),false); });
test('unknown mutation entity is rejected', () => { assert.throws(()=>applyMutation(emptyState(),{action:'save',entity:'__proto__',data:{}}),/inconnu/); });
test('invalid restored relationships are rejected', () => { const s=demoState(); s.leases[0].tenantId='foreign'; assert.throws(()=>applyMutation(emptyState(),{action:'restore',data:s}),/locataire/); });
const invoiceModule=await import(encode(compile(readFileSync(new URL('../lib/invoices.ts',import.meta.url),'utf8')).replace("'./model'",JSON.stringify(modelUrl))));
const spacesModule=await import(encode(compile(readFileSync(new URL('../lib/space-model.ts',import.meta.url),'utf8'))));
test('a duplicate property is rejected without changing existing data',()=>{const s=demoState();assert.throws(()=>save(s,'properties',{...s.properties[0],id:'new-property'}),/existe déjà/);assert.equal(s.properties.length,5);});
test('editing the existing property does not count as a duplicate',()=>{const s=demoState();const next=save(s,'properties',{...s.properties[0],description:'Information corrigée'});assert.equal(next.properties.length,5);});
test('a payment reference cannot be recorded twice for the same bill',()=>{const s=demoState();assert.throws(()=>save(s,'payments',{...s.payments[1],id:'duplicate-payment',amount:10000}),/référence/);});
test('legacy states and backups without signature fields remain valid',()=>{stateSchema.parse(demoState());});
test('signature SVG and HTML URLs are rejected',()=>{const s=demoState();assert.throws(()=>applyMutation(s,{action:'profile',data:{...s.profile,signature:'data:image/svg+xml;base64,AAAA'}}));assert.throws(()=>applyMutation(s,{action:'profile',data:{...s.profile,signature:'javascript:alert(1)'}}));});
test('a monthly invoice changes from pending to partial to paid from actual receipts',()=>{const s=demoState();const l=s.leases[2];const at=model.today();const make=state=>invoiceModule.invoiceSnapshot(state,l.id,l.firstMonth,'invoice-test',at+'T12:00:00Z');assert.equal(make(s).status,'En attente');const partial=save(s,'payments',{...s.payments[1],id:'partial-invoice',leaseId:l.id,amount:10000,reference:'PARTIEL'});assert.equal(make(partial).status,'Partiellement payée');const full=save(partial,'payments',{...s.payments[1],id:'full-invoice',leaseId:l.id,amount:85000,reference:'SOLDE'});assert.equal(make(full).status,'Payée');assert.equal(make(full).balance,0);assert.equal(make(s).balance,95000);});
test('invoice issuer and signature follow profile updates',()=>{const s=demoState();s.profile.company='Mon agence';s.profile.signature='data:image/png;base64,AAAA';const d=invoiceModule.invoiceSnapshot(s,s.leases[0].id,s.leases[0].firstMonth,'signature-test',model.today()+'T12:00:00Z');assert.equal(d.issuer.name,'Mon agence');assert.equal(d.issuer.signature,s.profile.signature);s.profile.signature='';assert.equal(invoiceModule.invoiceSnapshot(s,s.leases[0].id,s.leases[0].firstMonth,'signature-test',model.today()+'T12:00:00Z').issuer.signature,'');});
test('invoice HTML escapes untrusted names and instructions',()=>{const s=demoState();s.profile.company='<script>alert(1)</script>';s.profile.paymentInstructions='<img src=x onerror=alert(1)>';const d=invoiceModule.invoiceSnapshot(s,s.leases[0].id,s.leases[0].firstMonth,'safe-test',model.today()+'T12:00:00Z');const html=invoiceModule.invoiceHtml(d);assert.ok(!html.includes('<script>alert(1)</script>'));assert.ok(!html.includes('<img src=x'));assert.ok(html.includes('&lt;script&gt;'));});
test('documents cannot be created outside the tracked lease period',()=>{const s=demoState();assert.throws(()=>invoiceModule.invoiceSnapshot(s,s.leases[0].id,'2000-01','invalid',model.today()+'T12:00:00Z'),/bail/);});
test('the first workspace retains the original storage key',()=>{const d={activeId:'default',spaces:[{id:'default',name:'Mon agence',mode:'agency'}]};assert.equal(spacesModule.spaceKey('user-a','default',d),'user-a');});
test('workspace keys are scoped to the authenticated user',()=>{const d={activeId:'personal',spaces:[{id:'personal',name:'Mon patrimoine',mode:'owner'}]};assert.notEqual(spacesModule.spaceKey('user-a','personal',d),spacesModule.spaceKey('user-b','personal',d));assert.throws(()=>spacesModule.spaceKey('user-a','foreign',d),/inaccessible/);});
function setupFixture(){const s=model.emptyState();const at=model.today();return {s,property:{...model.demoState().properties[0],id:'setup-property'},tenant:{...model.demoState().tenants[0],id:'setup-tenant'},lease:{...model.demoState().leases[0],id:'setup-lease',propertyId:'setup-property',tenantId:'setup-tenant',startDate:at,endDate:'',firstMonth:at.slice(0,7)}};}
test('one rental setup saves its tenant, property and lease together',()=>{const {s,property,tenant,lease}=setupFixture();const next=applyMutation(s,{action:'startRental',data:{property,tenant,tenantId:tenant.id,lease}});assert.equal(next.tenants.length,1);assert.equal(next.properties.length,1);assert.equal(next.leases[0].propertyId,property.id);assert.equal(model.propertyStatus(next,property),'occupied');assert.equal(s.tenants.length,0);});
test('an invalid rental setup leaves all previous data intact',()=>{const {s,property,tenant,lease}=setupFixture();assert.throws(()=>applyMutation(s,{action:'startRental',data:{property,tenant,tenantId:tenant.id,lease:{...lease,rent:0}}}));assert.equal(s.properties.length,0);assert.equal(s.tenants.length,0);});
test('an existing tenant can be assigned without creating a second person',()=>{const {s,property,tenant,lease}=setupFixture();s.tenants.push(tenant);const next=applyMutation(s,{action:'startRental',data:{property,tenantId:tenant.id,lease}});assert.equal(next.tenants.length,1);assert.equal(next.leases[0].tenantId,tenant.id);});
test('a setup cannot silently overwrite an existing tenant',()=>{const {s,property,tenant,lease}=setupFixture();s.tenants.push(tenant);assert.throws(()=>applyMutation(s,{action:'startRental',data:{property,tenant,tenantId:tenant.id,lease}}),/déjà/);});
test('agency owner and entrusted property are saved together',()=>{const {s,property}=setupFixture();const owner={id:'new-owner',name:'Propriétaire test',phone:'',email:''};const next=applyMutation(s,{action:'saveProperty',data:{property:{...property,ownerId:owner.id},owner}});assert.equal(next.properties[0].ownerId,next.owners[0].id);assert.equal(model.propertyStatus(next,next.properties[0]),'available');});
test('late partial payments remain red and retain the correct balance',()=>{const s=model.demoState(),l=s.leases[1];const r=model.rentSituation(s,l,l.firstMonth,l.firstMonth+'-10');assert.equal(r.tone,'red');assert.equal(r.days,5);assert.equal(r.balance,175000);});
test('a fully settled rent is never marked overdue',()=>{const s=model.demoState(),l=s.leases[0];const r=model.rentSituation(s,l,l.firstMonth,l.firstMonth+'-20');assert.equal(r.tone,'green');assert.equal(r.days,0);});
test('reminders are prepared first and then explicitly confirmed sent',()=>{const s=model.demoState(),l=s.leases[1];const d={id:'test-reminder',leaseId:l.id,period:l.firstMonth,channel:'whatsapp',status:'prepared',message:'Rappel test'};const prepared=applyMutation(s,{action:'rentReminder',data:d});assert.equal(prepared.rentReminders[0].status,'prepared');assert.equal(prepared.rentReminders[0].sentAt,undefined);const sent=applyMutation(prepared,{action:'rentReminder',data:{...d,status:'sent'}});assert.equal(sent.rentReminders.length,1);assert.ok(sent.rentReminders[0].sentAt);assert.equal(sent.payments.length,s.payments.length);assert.equal(model.balanceFor(sent,l,l.firstMonth),175000);});
test('a reminder cannot be falsely marked sent without being prepared',()=>{const s=model.demoState(),l=s.leases[1];assert.throws(()=>applyMutation(s,{action:'rentReminder',data:{id:'unprepared',leaseId:l.id,period:l.firstMonth,channel:'copy',status:'sent',message:'Test'}}),/Préparez/);});
test('follow up opens the oldest unpaid overdue month',()=>{const s=model.demoState(),l=s.leases[2];assert.equal(model.followPeriod(s,l,model.addMonth(l.firstMonth,2)+'-10'),l.firstMonth);});
test('backups made before reminder history remain valid',()=>{const s=model.demoState();delete s.rentReminders;assert.doesNotThrow(()=>stateSchema.parse(s));});
test('first rent due date cannot precede the move in date',()=>{const l={...model.demoState().leases[0],startDate:'2026-10-17',firstMonth:'2026-10',dueDay:5};assert.equal(model.dueDate(l,'2026-10'),'2026-10-17');assert.equal(model.dueDate(l,'2026-11'),'2026-11-05');});
const dates=await import(encode(compile(readFileSync(new URL('../lib/dates.ts',import.meta.url),'utf8'))));
test('custom calendar accepts French dates and rejects impossible days',()=>{assert.equal(dates.parseDateInput('05/11/2026'),'2026-11-05');assert.equal(dates.parseDateInput('31/02/2026'),'');assert.equal(dates.parseDateInput('11/2026',true),'2026-11');});
test('deadline colors follow the actual remaining day count',()=>{for(const [due,tone] of [['2026-11-20','green'],['2026-11-11','yellow'],['2026-11-04','orange'],['2026-11-01','red'],['2026-10-30','red']])assert.equal(dates.deadlineInfo(due,'2026-11-01').tone,tone);});
test('first payment date can be chosen explicitly and later months retain their normal due day',()=>{const l={...model.demoState().leases[0],firstMonth:'2026-11',firstDueDate:'2026-11-20',dueDay:5};assert.equal(model.dueDate(l,'2026-11'),'2026-11-20');assert.equal(model.dueDate(l,'2026-12'),'2026-12-05');});
test('batch invoice setup records only the outstanding amounts and is idempotent',()=>{const s=model.demoState(),l=s.leases[1];const d={leaseId:l.id,from:l.startDate.slice(0,7),to:l.firstMonth,mode:'paid',method:'Wave',paymentDate:model.today(),received:true};const first=applyMutation(s,{action:'prepareBills',data:d});assert.equal(model.balanceFor(first,first.leases[1],d.from),0);assert.equal(model.balanceFor(first,first.leases[1],d.to),0);assert.equal(s.leases[1].firstMonth,l.firstMonth);const twice=applyMutation(first,{action:'prepareBills',data:d});assert.equal(twice.payments.length,first.payments.length);});
test('already paid invoices require explicit confirmation of money received',()=>{const s=model.demoState(),l=s.leases[1];assert.throws(()=>applyMutation(s,{action:'prepareBills',data:{leaseId:l.id,from:l.firstMonth,to:l.firstMonth,mode:'paid',method:'Wave',paymentDate:model.today(),received:false}}),/Confirmez/);});
test('invoice backfill cannot invent rent before the lease begins',()=>{const s=model.demoState(),l=s.leases[0];assert.throws(()=>applyMutation(s,{action:'prepareBills',data:{leaseId:l.id,from:'2000-01',to:'2000-02',mode:'overdue'}}),/bail/);});
test('pending invoice setup never deletes or fabricates payments',()=>{const s=model.demoState(),l=s.leases[1];const next=applyMutation(s,{action:'prepareBills',data:{leaseId:l.id,from:l.firstMonth,to:l.firstMonth,mode:'pending'}});assert.deepEqual(next.payments.map(({ownerId,commissionRate,rentBase,...p})=>p),s.payments);});
test('tenant identity is private while rental contact details are included on the document',()=>{const s=model.demoState(),l=s.leases[0];s.tenants[0].identityNumber='PRIVATE-IDENTITY-123';s.tenants[0].phone='+221770000000';s.tenants[0].photo='/api/files?key=photo';const d=invoiceModule.invoiceSnapshot(s,l.id,l.firstMonth,'privacy-test',model.today()+'T12:00:00Z');const html=invoiceModule.invoiceHtml(d);assert.ok(!html.includes('PRIVATE-IDENTITY-123'));assert.ok(html.includes('+221770000000'));stateSchema.parse(s);});
test('an optional first payment override can be cleared while editing a lease',()=>{const s=model.demoState();const l=s.leases[0];const next=applyMutation(s,{action:'save',entity:'leases',data:{...l,firstDueDate:''}});assert.equal(next.leases[0].firstDueDate,'');assert.equal(model.dueDate(next.leases[0],l.firstMonth),model.dueDate(l,l.firstMonth));});
function agencyFixture(){const s=demoState();s.profile.mode='agency';s.owners=[{id:'owner-a',name:'Propriétaire A',phone:'',email:'',status:'active'},{id:'owner-b',name:'Propriétaire B',phone:'',email:'',status:'active'}];s.properties[0].ownerId='owner-a';s.properties[1].ownerId='owner-a';s.properties[2].ownerId='owner-b';s.leases[0].commissionRate=10;s.leases[1].commissionRate=5;return s;}
const transfer=(s,patch={})=>({id:'transfer-a',ownerId:'owner-a',period:s.leases[0].firstMonth,amount:150000,date:model.today(),method:'Wave',reference:'REV-001',note:'Versement confirmé',confirmed:true,...patch});
test('one owner account consolidates several properties and separates charges and deposits',()=>{const s=agencyFixture(),a=ownerAccount(s,'owner-a',s.leases[0].firstMonth);assert.equal(a.rent,385000);assert.equal(a.charges,15000);assert.equal(a.commission,28500);assert.equal(a.expenses,18500);assert.equal(a.available,338000);assert.equal(ownerAccount(s,'owner-b',s.leases[0].firstMonth).available,0);});
test('a confirmed partial owner transfer reduces the available balance without changing rent receipts',()=>{const s=agencyFixture(),next=applyMutation(s,{action:'ownerTransfer',data:transfer(s)}),a=ownerAccount(next,'owner-a',s.leases[0].firstMonth);assert.equal(a.paid,150000);assert.equal(a.available,188000);assert.equal(totals(next,s.leases[0].firstMonth).collected,400000);assert.equal(next.ownerTransfers[0].status,'paid');assert.ok(next.ownerTransfers[0].createdAt);assert.equal(s.ownerTransfers,undefined);});
test('owner overpayments, unconfirmed payments and duplicate references are rejected',()=>{const s=agencyFixture();assert.throws(()=>applyMutation(s,{action:'ownerTransfer',data:transfer(s,{amount:338001})}),/solde/);assert.throws(()=>applyMutation(s,{action:'ownerTransfer',data:transfer(s,{confirmed:false})}));const next=applyMutation(s,{action:'ownerTransfer',data:transfer(s)});assert.throws(()=>applyMutation(next,{action:'ownerTransfer',data:transfer(s,{id:'another',amount:1})}),/référence/);assert.throws(()=>applyMutation(next,{action:'ownerTransfer',data:transfer(s)}),/déjà enregistré/);});
test('a cancelled owner transfer stays in history and restores its available balance',()=>{const s=agencyFixture(),paid=applyMutation(s,{action:'ownerTransfer',data:transfer(s)}),cancelled=applyMutation(paid,{action:'cancelOwnerTransfer',data:{id:'transfer-a',reason:'Erreur de saisie, aucun versement effectué'}});assert.equal(cancelled.ownerTransfers.length,1);assert.equal(cancelled.ownerTransfers[0].status,'cancelled');assert.ok(cancelled.ownerTransfers[0].cancelledAt);assert.equal(ownerAccount(cancelled,'owner-a',s.leases[0].firstMonth).available,338000);assert.throws(()=>applyMutation(cancelled,{action:'cancelOwnerTransfer',data:{id:'transfer-a',reason:'Encore'}}),/déjà annulé/);});
test('negative prior balances carry forward and reduce new amounts available for transfer',()=>{const s=agencyFixture();s.expenses.push({...s.expenses[0],id:'prior-cost',date:model.addMonth(s.leases[0].firstMonth,-1)+'-10',amount:50000});const a=ownerAccount(s,'owner-a',s.leases[0].firstMonth);assert.equal(a.opening,-50000);assert.equal(a.available,288000);assert.throws(()=>applyMutation(s,{action:'ownerTransfer',data:transfer(s,{amount:288001})}),/solde/);});
test('a backdated owner transfer cannot reuse money already transferred in a later month',()=>{const s=agencyFixture(),l=s.leases[0],prev=model.addMonth(l.firstMonth,-1);s.leases[0].firstMonth=prev;s.expenses=[];s.payments=[{...s.payments[0],id:'earlier',period:prev,amount:l.rent},{...s.payments[0],id:'now',amount:l.rent}];const available=ownerAccount(s,'owner-a',model.currentMonth()).available;const next=applyMutation(s,{action:'ownerTransfer',data:transfer(s,{period:model.currentMonth(),amount:available})});assert.throws(()=>applyMutation(next,{action:'ownerTransfer',data:transfer(s,{id:'backdated',reference:'REV-002',period:prev,amount:1})}),/solde/);});
test('inactive owners retain their properties and their financial history',()=>{const s=agencyFixture(),next=save(s,'owners',{...s.owners[0],status:'inactive'});assert.equal(next.owners[0].status,'inactive');assert.equal(next.properties.filter(p=>p.ownerId==='owner-a').length,2);assert.equal(ownerAccount(next,'owner-a',s.leases[0].firstMonth).available,338000);});
test('captured owner and commission remain unchanged when a property or contract changes',()=>{const s=agencyFixture();let next=save(s,'tasks',s.tasks[0]);next=save(next,'properties',{...next.properties[0],ownerId:'owner-b'});next=save(next,'leases',{...next.leases[0],commissionRate:25});assert.equal(ownerAccount(next,'owner-a',s.leases[0].firstMonth).rent,385000);assert.equal(ownerAccount(next,'owner-a',s.leases[0].firstMonth).commission,28500);assert.equal(ownerAccount(next,'owner-b',s.leases[0].firstMonth).rent,0);});
test('partial receipts use cumulative rounding and never commission recovered charges',()=>{const s=agencyFixture(),l=s.leases[0];s.payments=[{...s.payments[0],amount:1,id:'tiny-a'},{...s.payments[0],amount:1,id:'tiny-b'}];s.leases[0].commissionRate=50;let a=ownerAccount(s,'owner-a',l.firstMonth);assert.equal(a.commission,1);s.payments=[{...s.payments[0],id:'full',amount:l.rent+l.charges}];a=ownerAccount(s,'owner-a',l.firstMonth);assert.equal(a.commission,Math.round(l.rent/2));assert.equal(a.charges,l.charges);});
test('new receipt metadata is derived from its contract, not copied from another payment',()=>{const s=agencyFixture();const next=save(s,'payments',{...s.payments[0],id:'new-receipt',leaseId:s.leases[2].id,amount:10000,reference:'NEW',ownerId:'owner-a',commissionRate:99,rentBase:1});const p=next.payments.find(p=>p.id==='new-receipt');assert.equal(p.ownerId,'owner-b');assert.equal(p.commissionRate,0);assert.equal(p.rentBase,s.leases[2].rent);});
test('owners with transfer history cannot be deleted and future transfers cannot be invented',()=>{const s=agencyFixture(),next=applyMutation(s,{action:'ownerTransfer',data:transfer(s)});assert.throws(()=>applyMutation(next,{action:'delete',entity:'owners',data:{id:'owner-a'}}),/propriétaire/);assert.throws(()=>applyMutation(s,{action:'ownerTransfer',data:transfer(s,{date:'2099-01-01'})}),/effectué/);});
test('owner statements include real transfers and escape untrusted names and notes',()=>{const s=agencyFixture();s.owners[0].name='<img src=x onerror=alert(1)>';let next=applyMutation(s,{action:'ownerTransfer',data:transfer(s,{note:'<script>bad()</script>'})});const html=ownerStatementHtml(next,'owner-a',s.leases[0].firstMonth);assert.ok(html.includes('&lt;img'));assert.ok(!html.includes('<script>bad'));assert.ok(html.includes('150'));assert.ok(html.includes('REV-001'));assert.ok(!html.includes('identityNumber'));});
test('an overdue invoice can include the current month when its due date is already past',()=>{const s=demoState(),l=s.leases[1];if(model.dueDate(l,l.firstMonth)>=model.today())return;const next=applyMutation(s,{action:'prepareBills',data:{leaseId:l.id,from:l.firstMonth,to:l.firstMonth,mode:'overdue'}});assert.equal(next.payments.length,s.payments.length);assert.ok(model.balanceFor(next,next.leases[1],l.firstMonth)>0);});
test('left and right units on the same floor can have separate tenants simultaneously',()=>{const s=demoState(),p=s.properties[3];const units=[{...unit(p,'left-flat','RDC gauche'),floor:'RDC'},{...unit(p,'right-flat','RDC droite'),floor:'RDC'}];let next=applyMutation(s,{action:'addUnits',data:{propertyId:p.id,units}});next=save(next,'leases',{...s.leases[0],id:'lease-left',propertyId:'left-flat',tenantId:s.tenants[0].id});next=save(next,'leases',{...s.leases[0],id:'lease-right',propertyId:'right-flat',tenantId:s.tenants[1].id});assert.equal(model.propertyUnits(next,p).length,2);assert.equal(model.leaseFor(next,'left-flat').tenantId,s.tenants[0].id);assert.equal(model.leaseFor(next,'right-flat').tenantId,s.tenants[1].id);assert.equal(model.rentalProperties(next).filter(p=>p.parentId===s.properties[3].id).length,2);});
const contractRequest=(s,patch={})=>({action:'createContract',data:{id:'contract-test',leaseId:s.leases[0].id,title:'Contrat de location',usage:'Habitation',clauses:'État des lieux et charges à préciser entre les parties.',...patch}});
