test('a real signed copy and date are archived together and cannot be silently overwritten',()=>{const s=demoState(),draft=applyMutation(s,contractRequest(s)),next=applyMutation(draft,{action:'signContract',data:{id:'contract-test',date:model.today(),fileUrl:'/api/files?key=signed.pdf'}});assert.equal(next.rentalContracts[0].status,'signed');assert.equal(next.rentalContracts[0].signedFile,'/api/files?key=signed.pdf');assert.throws(()=>applyMutation(next,{action:'signContract',data:{id:'contract-test',date:model.today(),fileUrl:'/api/files?key=other.pdf'}}),/déjà/);});
