test('correcting stock quantity preserves historical availability',()=>{const s=move(addAsset(inventoryState()),'out-1','out',3);assert.throws(()=>addAsset(s,{...s.assets[0],quantity:2}),/disponibles/);assert.equal(s.assets[0].quantity,4);});
