test('a handover cannot be cancelled while a dependent return remains',()=>{let s=move(addAsset(inventoryState()),'out-1','out',2);s=move(s,'return-1','return',1);assert.throws(()=>applyMutation(s,{action:'cancelAssetMovement',data:{id:'out-1',reason:'Erreur'}}),/cette personne/);s=applyMutation(s,{action:'cancelAssetMovement',data:{id:'return-1',reason:'Erreur'}});s=applyMutation(s,{action:'cancelAssetMovement',data:{id:'out-1',reason:'Erreur'}});assert.equal(inventory.assetBalance(s,s.assets[0]).available,4);});
