test('a tenant can rent a newly identified left-side unit in an existing empty building atomically',()=>{
 const s=demoState(),parent=s.properties[3],child=unit(parent,'new-left','R+2 · Gauche · Appartement A'),tenant={id:'new-occupant',name:'Samba Nouveau',phone:'',email:'',notes:''};
 const next=applyMutation(s,{action:'startRental',data:{tenant,tenantId:tenant.id,property:child,lease:{...s.leases[0],id:'new-left-lease',propertyId:child.id,tenantId:tenant.id}}});
 assert.equal(next.tenants.find(t=>t.id===tenant.id).name,tenant.name);
 assert.equal(next.leases.find(l=>l.id==='new-left-lease').propertyId,child.id);
 assert.equal(model.propertyUnits(next,parent).length,1);
 assert.equal(next.properties.find(p=>p.id===child.id).ownerId,parent.ownerId);
 assert.equal(s.tenants.some(t=>t.id===tenant.id),false);
});
test('creating a tenant and splitting an occupied house preserves previous rent history and receipts',()=>{
 const s=demoState(),parent=s.properties[0],oldLease=s.leases.find(l=>l.propertyId===parent.id),oldPayments=s.payments.filter(p=>p.leaseId===oldLease.id);
 const child=unit(parent,'right-unit','R+1 · Droite'),existingUnit=unit(parent,'old-left-unit','RDC · Gauche');
 const next=applyMutation(s,{action:'startRental',data:{tenantId:s.tenants[1].id,property:child,existingUnit,lease:{...oldLease,id:'right-new-lease',propertyId:child.id,tenantId:s.tenants[1].id}}});
 assert.equal(next.leases.find(l=>l.id===oldLease.id).propertyId,existingUnit.id);
 assert.equal(next.leases.find(l=>l.id==='right-new-lease').propertyId,child.id);
 assert.deepEqual(next.payments.filter(p=>p.leaseId===oldLease.id).map(p=>p.id),oldPayments.map(p=>p.id));
 assert.equal(model.propertyUnits(next,parent).length,2);
 assert.equal(oldLease.propertyId,parent.id);
});
